<?php
require_once __DIR__.'/config.php';require_login();$pageTitle='My uploads';$stmt=$pdo->prepare("SELECT r.*,s.name subject_name,c.name category_name FROM resources r JOIN subjects s ON s.id=r.subject_id JOIN categories c ON c.id=r.category_id WHERE uploader_id=? ORDER BY created_at DESC");$stmt->execute([current_user()['id']]);$rows=$stmt->fetchAll();
if(is_post()){verify_csrf();$id=valid_id($_POST['id']??0);$r=owned_resource($pdo,$id,(int)current_user()['id']);if(!$r){set_flash('error','Resource not found.');redirect('my-uploads.php');}
if(($_POST['action']??'')==='delete'){if($r['file_path']&&is_file(__DIR__.'/'.$r['file_path']))unlink(__DIR__.'/'.$r['file_path']);$pdo->prepare('DELETE FROM resources WHERE id=? AND uploader_id=?')->execute([$id,current_user()['id']]);set_flash('success','Resource deleted.');redirect('my-uploads.php');}
if(($_POST['action']??'')==='edit'){ $title=posted_string('title',180);$description=posted_string('description',5000);if(mb_strlen($title)<4||mb_strlen($description)<15){set_flash('error','Please provide a valid title and description.');redirect('my-uploads.php');}$pdo->prepare("UPDATE resources SET title=?,description=?,status='pending',reject_reason=NULL WHERE id=? AND uploader_id=?")->execute([$title,$description,$id,current_user()['id']]);set_flash('success','Resource updated and sent for review again.');redirect('my-uploads.php');}}
require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><span class="eyebrow">YOUR CONTRIBUTIONS</span><h1>My uploads</h1><p>See which resources are pending review, approved, or need changes.</p></div></section><div class="page-content"><div class="container"><?php if($rows): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Resource</th><th>Subject</th><th>Status</th><th>Uploaded</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['title']) ?></strong><?php if($r['reject_reason']): ?><div class="small-muted">Feedback: <?= e($r['reject_reason']) ?></div><?php endif; ?></td><td><?= e($r['subject_name']) ?></td><td><?= badge($r['status']) ?></td><td><?= e(date('M j, Y',strtotime($r['created_at']))) ?></td><td><details><summary>Edit / delete</summary><form method="post" class="mt-1"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="edit"><div class="form-group"><label>Title</label><input name="title" value="<?= e($r['title']) ?>" required></div><div class="form-group"><label>Description</label><textarea name="description" required><?= e($r['description']) ?></textarea></div><button class="btn btn-primary btn-small">Save changes</button></form><form method="post" data-confirm="Delete this resource permanently?" class="mt-1"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger btn-small">Delete</button></form></details></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><div class="empty-icon">📄</div><h3>No uploads yet</h3><p>Share your first resource and help another student learn.</p><a class="btn btn-primary" href="upload.php">Upload a resource</a></div><?php endif; ?></div></div>
<?php require __DIR__.'/includes/footer.php';?>
